import {author,question as q,checkpoint as cp} from './content-helpers.mjs';
export const lessons={},checkpoints={};
const a=(...args)=>author(lessons,...args);
a('01.01','ชื่ออักษรใช้เวลาสะกดชื่อ แต่เสียงในคำใช้เวลาอ่าน เช่นชื่อ B คือ /biː/ ส่วนเสียงต้นของ bag คือ /b/ ตัวอักษรหนึ่งตัวแทนเสียงได้หลายแบบ และบางกลุ่มอักษรแทนเสียงเดียว เริ่มจากชื่อของคุณและคำที่ใช้จริง ไม่ต้องท่องตาราง A–Z ให้จบก่อน ตัวใหญ่กับตัวเล็กเป็นอักษรเดียวกันแต่ใช้ต่างตำแหน่ง','B / b — bag~ชื่ออักษร B ต่างจากเสียง /b/ ใน bag||M / m — Mai~ชื่อเฉพาะ Mai เริ่มด้วยตัวใหญ่','อย่าอ่านคำโดยเอาชื่ออักษรแต่ละตัวมาต่อกัน และอย่าใช้ตัวใหญ่ทุกคำในประโยค',q('เมื่อบอกเพื่อนให้เขียนชื่อ Ben คุณกำลังใช้สิ่งใด?','ชื่ออักษร B–E–N|เสียง /b/ เพียงเสียงเดียว|ชื่ออักษรแปลความหมายชื่อ',0,'การสะกดบอกชื่ออักษรทีละตัว ส่วนการอ่าน Ben ออกเป็นคำ'),q('คำใดใช้ตัวใหญ่เหมาะสม?','my name is mai.|My name is Mai.|MY name IS mai.',1,'ต้นประโยค My และชื่อเฉพาะ Mai ใช้ตัวใหญ่'),'สะกดชื่อของคุณด้วยชื่ออักษร จากนั้นอ่านชื่อเป็นคำหนึ่งครั้ง แล้วเขียน My name is …','My name is Ben. B–E–N.');
a('01.02','ใช้หูและตำแหน่งปากช่วยแยกเสียง /r/ กับ /l/ และ /v/ กับ /w/ สำหรับ /l/ ปลายลิ้นแตะบริเวณหลังฟันบน ส่วน /r/ ในสำเนียงอเมริกันไม่แตะตำแหน่งนั้น /v/ ใช้ฟันบนแตะริมฝีปากล่างและมีเสียงสั่น /w/ เริ่มจากริมฝีปากกลม th อาจเป็น /θ/ ใน think หรือ /ð/ ใน this; sh /ʃ/ ต่างจาก ch /tʃ/ ที่มีช่วงกักเสียงก่อนปล่อย','light / right~คู่เสียงต้นต่างกัน ความหมายจึงต่าง||vest / west~เสื้อกั๊ก / ทิศตะวันตก||ship / chip~sh กับ ch ไม่ใช่เสียงเดียวกัน','ฝึกช้าแล้วเพิ่มความเร็วโดยไม่เพิ่มสระแทรก ไม่ต้องเลียนสำเนียงเดียวให้เหมือนทั้งหมด เป้าหมายคือให้ผู้ฟังแยกคำได้',q('คู่ใดใช้เสียงเริ่ม /v/ กับ /w/?','vest / west|light / right|ship / chip',0,'vest เริ่ม /v/; west เริ่ม /w/'),q('คำว่า think กับ this มี th แบบใด?','เสียงเดียวกันทุกตำแหน่ง|think ไม่มีเสียงสั่น ส่วน this มีเสียงสั่น|th อ่านเป็น t เสมอ',1,'/θ/ ใน think ไม่ก้อง ส่วน /ð/ ใน this ก้อง'),'ฟังเสียงจากพจนานุกรมของ light/right และ vest/west แล้วพูดแต่ละคู่สลับกันสามรอบ ให้ผู้ฟังชี้คำที่ได้ยิน','light — right; vest — west. หากเพื่อนชี้ผิด ให้ลดความเร็วและตรวจตำแหน่งปากก่อนลองใหม่');
a('01.03','เสียงสระเป็นส่วนสำคัญของคำ ship /ʃɪp/ กับ sheep /ʃiːp/ ต่างทั้งคุณภาพสระและความยาว ไม่ใช่เพียงยืดเสียงเดิม bed /bed/ ต่างจาก bad /bæd/ ตัวสะกดภาษาอังกฤษไม่จับคู่กับเสียงแบบหนึ่งต่อหนึ่ง เช่น ea ใน tea กับ bread ออกเสียงต่างกัน จึงตรวจเสียงของทั้งคำพร้อมฟังและอ่าน','ship / sheep~เรือ / แกะ: เสียงสระต่างกัน||bed / bad~เตียง / ไม่ดี||tea / bread~ea เขียนเหมือนกัน แต่เสียงต่าง','การถอดเสียงด้วยอักษรไทยช่วยเริ่มได้ แต่ไม่แทนรายละเอียดของเสียงจริง ตรวจเสียงคำเต็มเสมอ',q('คู่ใดต่างที่เสียงสระเป็นหลัก?','ship / sheep|vest / west|light / right',0,'ship /ʃɪp/ และ sheep /ʃiːp/ มีพยัญชนะต้นท้ายเหมือนกัน'),q('ea ใน tea และ bread บอกอะไร?','อักษรกลุ่มเดียวกันมีได้หลายเสียง|ea ต้องอ่าน /iː/ เสมอ|ตัวสะกดไม่เกี่ยวกับเสียงเลย',0,'tea ใช้ /iː/ แต่ bread ใช้ /e/ จึงดูคำเต็มประกอบ'),'ฟัง ship/sheep และ bed/bad จดว่าคำใดออกเสียงยาก จากนั้นพูดประโยคสั้นพร้อมคำเป้าหมาย','A sheep is on the ship. This bed is bad.');
a('01.04','เสียงท้ายคำช่วยบอกทั้งคำศัพท์และไวยากรณ์ cap /kæp/ กับ cat /kæt/ ต่างเสียงท้าย ต้องคงตำแหน่งปากแม้บางสำเนียงไม่ปล่อยเสียง /t/ ชัดทุกครั้ง กลุ่มพยัญชนะเช่น /st/ ใน stop และ /ks/ ใน books ไม่ต้องเติมเสียงสระระหว่างกลาง ลองแยกเสียงช้าแล้วรวมเป็นพยางค์เดียว','cap / cat~ต่างเสียงท้าย /p/ และ /t/||book / books~books มีเสียงท้าย /ks/ บอกหลายเล่ม||stop~เริ่มด้วย /st/ โดยไม่มีสระแทรก','ไม่อ่าน books เป็นสองพยางค์ และไม่ละเสียงท้ายทุกคำเพราะอาจเปลี่ยนความหมาย',q('book กับ books ต่างกันอย่างไร?','books มีเสียงท้ายและรูปพหูพจน์|books มีสระเพิ่มหนึ่งพยางค์เสมอ|ไม่มีความต่าง',0,'เสียง /s/ ที่เพิ่มทำให้เป็น books หลายเล่ม'),q('คำว่า stop ควรเริ่มอย่างไร?','/s/ ต่อ /t/ โดยไม่มีสระแทรก|เติมเสียงอะระหว่าง s กับ t|ละ t',0,'กลุ่ม /st/ อยู่ในพยางค์เดียวกัน'),'อ่าน cap/cat และ book/books แล้วบันทึกเสียง ตรวจว่ามีเสียงท้ายและไม่มีสระที่เพิ่มเอง','cap — cat; one book — two books; stop.');
a('01.05','กลุ่มตัวสะกดช่วยเดาเสียงเบื้องต้นได้ เช่น sh ใน shop, ch ใน chair, th ใน three; แต่ ch ใน school ไม่เป็น /tʃ/ เสมอ silent e อาจเปลี่ยนเสียงสระ เช่น cap/cape ส่วนตัวเงียบใน know และ walk ต้องเรียนเป็นคำ กลุ่มสระ ai ใน rain เป็นแนวทางที่ใช้บ่อย ไม่ใช่กฎที่รับรองทุกคำ','cap / cape~e ท้ายไม่ออกเสียง แต่สัมพันธ์กับสระที่เปลี่ยน||rain / train~ai มักออกเสียง /eɪ/||know / walk~k ใน know และ l ใน walk ไม่ออกเสียงในสำเนียงมาตรฐานทั่วไป','ตัวสะกดให้ข้อสันนิษฐาน แล้วใช้เสียงพจนานุกรมตรวจ อย่าบอกว่า ch หรือ silent e ใช้กฎเดียวทุกคำ',q('เสียงต้นของ know ในสำเนียงทั่วไปคืออะไร?','/n/|/k/|/kn/ มีสองเสียง',0,'k เป็นตัวเงียบใน know'),q('คู่ใดแสดงรูป silent e ที่เปลี่ยนสระ?','cap / cape|cat / cats|go / goes',0,'cape มี e ท้ายเงียบและเสียงสระ /eɪ/ ต่างจาก cap'),'เลือกคำใหม่สามคำที่มี sh/ch/ai หรือ silent e ลองเดาแล้วฟังตรวจ เขียนจุดที่เดาถูกและต้องแก้','shop: sh /ʃ/; rain: ai /eɪ/; cape: a /eɪ/ และ e เงียบ');
a('01.06','พยางค์คือช่วงเสียงที่มีแกนสระ เช่น teacher มีสองพยางค์และเน้นพยางค์แรก ส่วน banana มีสามพยางค์และเน้นพยางค์ที่สอง พยางค์เน้นมักชัด ยาว หรือเด่นกว่าพยางค์อื่น สัญลักษณ์ ˈ อยู่ก่อนพยางค์เน้นในพจนานุกรม และ /ə/ เป็นเสียง schwa ที่พบบ่อยในพยางค์ไม่เน้น ตรวจชนิดสำเนียงและปุ่มเสียงควบคู่กัน','TEA-cher~teacher เน้นพยางค์แรก||ba-NA-na~banana เน้นพยางค์กลาง||a-BOUT~about เน้นพยางค์ที่สอง ส่วน a มักเป็น /ə/','อย่าเน้นทุกพยางค์เท่ากันหรือนับพยางค์จากจำนวนตัวสระที่เขียน',q('banana โดยทั่วไปเน้นพยางค์ใด?','แรก|กลาง|ท้าย',1,'banana เน้น NA; ฟังทั้งคำเพื่อได้จังหวะ'),q('สัญลักษณ์ ˈ ในรายการเสียงช่วยบอกอะไร?','พยางค์ที่มี stress|คำพหูพจน์|คำที่ไม่ต้องอ่าน',0,'เครื่องหมายอยู่หน้าพยางค์เน้น'),'เปิดพจนานุกรมของ teacher, banana และ about ฟังแล้วเคาะจังหวะพยางค์เน้น บันทึกคำที่คุณใช้จริงเพิ่มสองคำ','TEAcher; baNAna; aBOUT. คำของฉัน: STUdent และ toDAY.');
a('02.01','คำมีหน้าที่ต่างกัน noun เรียกคนหรือสิ่ง; pronoun แทน noun; verb บอกการกระทำหรือสภาพ; adjective บรรยาย noun; adverb ขยายการกระทำหรือระดับ; determiner ชี้หรือกำหนด noun; preposition เชื่อมความสัมพันธ์; conjunction เชื่อมความคิด ดูหน้าที่จากประโยค เพราะคำเดียวอาจทำหน้าที่ต่างกัน','The small cat sleeps quietly.~The กำหนด noun, small บรรยาย cat, sleeps เป็น verb, quietly เป็น adverb||She reads in the room and smiles.~She แทนคน, in เชื่อมตำแหน่ง, and เชื่อมการกระทำ','ชื่อชนิดคำเป็นเครื่องมือช่วยเรียงประโยค ไม่ต้องจำชื่อทั้งหมดก่อนเริ่มใช้ และอย่าตัดสินจากคำโดดอย่างเดียว',q('ใน a red bag คำ red ทำหน้าที่อะไร?','adjective|verb|preposition',0,'red บรรยายสีของ bag'),q('ใน They work here คำ They ทำหน้าที่อะไร?','noun ชื่อสถานที่|pronoun แทนกลุ่มคน|adverb',1,'They แทนกลุ่มคนที่เป็นประธาน'),'แยกหน้าที่คำใน The blue bird flies แล้วแต่งอีกหนึ่งประโยค','The: determiner; blue: adjective; bird: noun; flies: verb. My small dog runs.');
a('02.02','ประโยคบอกเล่าทั่วไปต้องมีประธานว่าใครหรืออะไร และกริยาว่าทำอะไรหรือมีสภาพอย่างไร ลำดับพื้นฐานคือ subject + verb ประธานอาจเป็นชื่อ กลุ่มคำนามหรือสรรพนาม แม้ภาษาไทยละประธานได้ในบางบริบท ประโยคอังกฤษทั่วไปยังต้องใส่ it/they/I ให้ชัด คำสั่งอย่าง Sit down. เป็นข้อยกเว้นที่เรียนภายหลัง','Birds fly.~Birds ประธาน; fly กริยา||Mai works.~Mai ประธาน; works กริยา','Runs fast. ยังไม่มีประธานหากตั้งใจใช้เป็นประโยคบอกเล่าปกติ ให้เขียน She runs fast.',q('ประโยคใดมีทั้งประธานและกริยา?','My friend.|My friend runs.|Runs in the park.',1,'My friend เป็นประธานและ runs เป็นกริยา'),q('ใน The children play คำใดเป็นประธาน?','The children|play|children play',0,'กลุ่มคำนาม The children บอกว่าใครทำ'),'เขียนสามประโยคเกี่ยวกับคนหรือสัตว์ ขีดเส้นใต้ประธานและวงกริยา','I read. Ben walks. Birds sing.');
a('02.03','บางกริยาต้องมีกรรมเพื่อบอกสิ่งหรือผู้รับการกระทำ เช่น I read books. มี books เป็นกรรม แต่ Birds fly. สมบูรณ์ได้โดยไม่ต้องมีกรรม กรรมมักอยู่หลังกริยาในประโยคพื้นฐาน อย่าสับสนกรรมกับข้อมูลสถานที่ เช่น in the park บอกที่ ไม่ใช่สิ่งที่ read อ่าน','I read books.~I ประธาน, read กริยา, books กรรม||Birds fly in the sky.~fly ไม่ต้องมีกรรม; in the sky บอกที่','ไม่ใช่ทุกคำหลังกริยาเป็นกรรม และไม่ใช่ทุกประโยคต้องมีกรรม',q('ใน Ben drinks water กรรมคือคำใด?','Ben|drinks|water',2,'water เป็นสิ่งที่ Ben ดื่ม'),q('ประโยคใดสมบูรณ์โดยไม่ต้องมีกรรม?','Birds fly.|She puts.|She gives.',0,'fly ใช้แบบไม่รับกรรมได้; puts/gives ต้องมีส่วนที่ตามในรูปตัวอย่างนี้'),'แต่งประโยคมีกับไม่มีกรรมอย่างละสองประโยค','I eat rice. She reads a book. Birds sing. We walk.');
a('02.04','ถ้าบอกว่าใครเป็นอะไรหรือเป็นอย่างไร ใช้ subject + be + complement เช่น I am a student. และ She is happy. ส่วนเติมเต็มไม่ได้เป็นสิ่งที่ได้รับการกระทำ แต่บอกข้อมูลของประธาน be ในรูปปัจจุบันคือ am/is/are ต่างจากกริยาทั่วไปอย่าง work จึงไม่เติม be นำหน้ากริยาทั่วไปโดยอัตโนมัติ','Ben is a teacher.~a teacher บอกว่า Ben เป็นอะไร||Ben teaches English.~teaches คือการกระทำ; English เป็นกรรม','I am happy. ถูก แต่ I am work. ไม่ใช่ Present Simple ที่ถูก ให้ใช้ I work.',q('เลือกประโยคบอกสภาพที่ถูกต้อง','She happy.|She is happy.|She is smiles.',1,'happy เป็น adjective จึงใช้ is เชื่อมประธานกับสภาพ'),q('ข้อใดเป็นการกระทำด้วยกริยาทั่วไป?','I am a cook.|I cook rice.|I am tired.',1,'cook เป็น verb และ rice เป็นกรรม'),'เขียนข้อมูลตัวตนสองประโยคและการกระทำสองประโยค','I am a student. I am happy. I read books. I study English.');
a('02.05','เริ่มประโยคด้วยตัวใหญ่ ใช้ I ตัวใหญ่เสมอและใช้ตัวใหญ่กับชื่อเฉพาะ เว้นช่องระหว่างคำและจบประโยคบอกเล่าด้วย full stop คำถามใช้ question mark ลำดับคำช่วยให้ผู้อ่านรู้ว่าใครทำอะไร คำคือหน่วยหนึ่ง; วลีเช่น a small bag ยังไม่ใช่ประโยคเต็ม; ประโยคอย่าง The bag is small. มีประธานและกริยา','I live in Bangkok.~I และ Bangkok ตัวใหญ่ มีช่องและจุดท้าย||Is the bag small?~คำถามใช้ ?||a small bag~เป็นวลีคำนาม ยังไม่เป็นประโยคเต็ม','ไม่ใช้ตัวใหญ่กลางคำทั่วไปเพียงเพื่อเน้น และไม่ต่อทุกประโยคโดยไม่มีเครื่องหมาย',q('ข้อใดเขียนถูกตามพื้นฐาน?','i live in bangkok.|I live in Bangkok.|I Live In Bangkok',1,'I ชื่อ Bangkok และต้นประโยคใช้ตัวใหญ่; มี full stop'),q('ข้อใดเป็นประโยคเต็ม?','a red bag|the small room|The room is small.',2,'มีประธาน The room กับกริยา is'),'แก้ i am ben i live in thailand ให้เป็นสองประโยค แล้วเขียนคำถามหนึ่งประโยค','I am Ben. I live in Thailand. Are you a student?');
a('03.01','คำนามเรียกคน สิ่งของ สถานที่และแนวคิด คำนามทั่วไปเช่น city ใช้กล่าวเป็นประเภท ส่วนชื่อเฉพาะเช่น Bangkok ระบุชื่อและขึ้นต้นตัวใหญ่ คำนามรูปธรรมอย่าง chair สัมผัสหรือสังเกตได้ ส่วน happiness เป็นแนวคิดหรือความรู้สึกที่นับเป็นชิ้นไม่ได้แบบเก้าอี้ อย่าเลือก article จากความเป็นรูปธรรมเพียงอย่างเดียว','city / Bangkok~ประเภทเมือง / ชื่อเมืองเฉพาะ||chair / happiness~สิ่งของ / แนวคิด||teacher / Mai~ประเภทบุคคล / ชื่อบุคคล','ภาษาและสัญชาติใช้ตัวใหญ่ เช่น English และ Thai แม้อยู่กลางประโยค',q('ข้อใดเป็นชื่อเฉพาะ?','school|Bangkok|happiness',1,'Bangkok คือชื่อเมืองเฉพาะ'),q('คำใดเป็นคำนามแนวคิด?','chair|bag|happiness',2,'happiness บอกความสุข ไม่ใช่สิ่งที่นับเป็นชิ้นแบบ bag'),'จัดคำห้าคำรอบตัวเป็นชื่อทั่วไปหรือชื่อเฉพาะ แล้วเขียนหนึ่งประโยค','city → Bangkok; person → Mai; language → English. Mai lives in Bangkok.');
a('03.02','ใช้ I แทนผู้พูด; you แทนผู้ฟังหนึ่งหรือหลายคน; we รวมผู้พูดกับคนอื่น; they แทนกลุ่มหรือคนที่กล่าวถึง; he/she แทนบุคคลตามบริบท; it แทนสิ่งของ สัตว์หรือสภาพที่กำลังกล่าวถึง Subject pronouns ใช้เป็นประธาน ไม่เปลี่ยนตามจำนวนคำภาษาไทย และ they ใช้กับบุคคลหนึ่งคนได้เมื่อไม่ทราบหรือไม่ต้องระบุเพศ','Mai is here. She is happy.~She อ้างกลับ Mai||Ben and I are friends. We study English.~We รวมผู้พูด||You are welcome.~you อาจเป็นผู้ฟังหนึ่งคนหรือหลายคน','ต้องทำให้ชัดว่า it/they อ้างถึงอะไร ถ้ามีหลายสิ่งให้ใช้ชื่อซ้ำเพื่อความชัดเจน',q('Ben and I ใช้ pronoun ใดแทนเป็นประธาน?','we|they|he',0,'รวมผู้พูด I จึงใช้ we'),q('you ใช้กับใครได้?','ผู้ฟังหนึ่งคนเท่านั้น|ผู้ฟังหลายคนเท่านั้น|ผู้ฟังหนึ่งหรือหลายคน',2,'รูป you ใช้ทั้งเอกพจน์และพหูพจน์'),'เขียนประโยคด้วย I, you, we, they, he, she, it โดยระบุว่าแต่ละคำแทนใคร','Mai → She is a student. Ben and Mai → They are friends. Ben and I → We are friends.');
a('03.03','คำนามนับได้มีเอกพจน์และพหูพจน์ ปกติเติม s เช่น books ถ้าท้ายเป็น s/sh/ch/x มักเติม es เช่น boxes ส่วนพยัญชนะ + y เปลี่ยน y เป็น ies เช่น city/cities แต่สระ + y เติม s เช่น toys เสียงท้ายพหูพจน์มี /s/ ใน books, /z/ ใน bags และ /ɪz/ ใน buses ดูทั้งเสียงและตัวสะกด','one book / two books~หนึ่งเล่ม / สองเล่ม||one box / three boxes~เติม es||one city / two cities~พยัญชนะ + y → ies||one toy / four toys~สระ + y เติม s','s ของคำนามบอกหลายสิ่ง ส่วน s ของกริยาจะเรียนใน M08; อย่าเปลี่ยน y ทุกคำ',q('พหูพจน์ของ baby คืออะไร?','babys|babies|babyes',1,'พยัญชนะ b อยู่หน้า y จึงเปลี่ยน y เป็น ies'),q('พหูพจน์ของ key คืออะไร?','keies|keys|keyes',1,'e เป็นสระหน้า y จึงเติม s'),'เลือกสิ่งของสามชนิด เขียนจำนวนหนึ่งและหลาย แล้วอ่านเสียงท้าย','one cup / two cups; one bag / three bags; one bus / two buses.');
a('03.04','คำนามบางคำเปลี่ยนรูปเมื่อเป็นพหูพจน์ เช่น child/children, person/people, man/men, woman/women ไม่ใช้กฎเติม s ตามปกติ บางคำคงรูป เช่น one sheep/two sheep และ fish ในบริบททั่วไป รูป persons/fishes มีบริบทเฉพาะ แต่เริ่มจากรูปที่ใช้บ่อยและตรวจพจนานุกรมเมื่อจำเป็น','one child / two children~ไม่ใช่ childs||one person / five people~people เป็นรูปที่ใช้ทั่วไป||one sheep / three sheep~รูปคงเดิม','people เป็นพหูพจน์ในความหมายคนหลายคน ใช้ are ไม่ใช่ is',q('เลือกกลุ่มคำนามที่ถูก','two childs|two children|two childrens',1,'children เป็นรูปพหูพจน์อยู่แล้ว ไม่เติม s อีก'),q('one woman → two …','women|womans|womens',0,'woman เปลี่ยนเป็น women'),'เขียนภาพสมมติที่มีเด็ก คนและแกะ พร้อมจำนวนอย่างละหนึ่งประโยค','There are two children, three people and four sheep.');
a('03.05','คำนามนับได้แยกเป็นหน่วย เช่น a cup/two cups ส่วนคำนามนับไม่ได้เช่น water/rice ใช้เป็นปริมาณโดยไม่เติม s ในความหมายนั้น ถ้าต้องการนับให้มีหน่วย เช่น two cups of water ความเป็นนับได้ขึ้นอยู่กับความหมาย เช่น chicken คือเนื้อไก่อาจนับไม่ได้ แต่ a chicken หมายถึงไก่หนึ่งตัว','a chair / two chairs~นับเป็นตัวได้||water / two glasses of water~นับปริมาณผ่านแก้ว||chicken / a chicken~เนื้อไก่ / ไก่หนึ่งตัว','ไม่ใช้ a water ในความหมายของน้ำทั่วไป รูป a water ในร้านอาจหมายถึงหนึ่งแก้วหรือขวดตามบริบท',q('ข้อใดเหมาะกับน้ำทั่วไป?','a water|some water|two waters ในทุกบริบท',1,'water ในความหมายทั่วไปเป็น uncountable; ใช้ some water'),q('ข้อใดนับเป็นหน่วยได้โดยตรง?','rice|furniture|chair',2,'chair เป็น countable; rice และ furniture เป็น uncountable ในความหมายทั่วไป'),'แยกของรอบตัวห้าชนิดว่าใช้หน่วยใดเมื่อนับ','two chairs; three books; two glasses of water; one bowl of rice; a piece of furniture.');
a('04.01','เลือก be ตามประธาน: I am; he/she/it และคำนามเอกพจน์ is; you/we/they และคำนามพหูพจน์ are รูปนี้ใช้กับข้อมูลตัวตน สภาพหรือตำแหน่ง ดูหัวของกลุ่มคำนาม เช่น My friends เป็นหลายคนแม้เริ่มด้วย My','I am ready.~I ใช้ am||The teacher is here.~teacher หนึ่งคนใช้ is||My friends are here.~friends หลายคนใช้ are','you ใช้ are แม้พูดกับคนเดียว และชื่อ Mai ใช้ is เหมือน she',q('My sister … a student.','am|is|are',1,'My sister เป็นประธานเอกพจน์ จึงใช้ is'),q('You … welcome.','is|am|are',2,'you ใช้ are เสมอในรูปนี้'),'เขียนประโยคด้วยประธานชื่อคน คำนามเอกพจน์และพหูพจน์','Mai is ready. The room is small. The books are new.');
a('04.02','ใช้ be เชื่อมประธานกับชื่อ อาชีพ สัญชาติ ความรู้สึกและตำแหน่ง อาชีพที่เป็นคำนามนับได้เอกพจน์ใช้ a/an เช่น a nurse; nationality adjective เช่น Thai ไม่ต้องมี a; ความรู้สึก adjective เช่น tired ไม่เติม article; ตำแหน่งใช้กลุ่มคำเช่น at home','She is a nurse.~อาชีพใช้ a||She is Thai.~สัญชาติ adjective||She is tired.~บอกสภาพ||She is at home.~บอกตำแหน่ง','ไม่เขียน She is a tired. เมื่อ tired เป็น adjective เดี่ยว แต่ a tired nurse ได้เมื่อมี noun',q('ข้อใดบอกอาชีพถูก?','He is teacher.|He is a teacher.|He a teacher.',1,'teacher เป็นคำนามนับได้เอกพจน์จึงใช้ a และมี is'),q('ข้อใดบอกความรู้สึกถูก?','I am happy.|I am a happy.|I happy.',0,'happy เป็น adjective ใช้ am โดยไม่ต้องมี a'),'บอกอาชีพ สัญชาติ ความรู้สึกและที่อยู่ปัจจุบันอย่างละหนึ่งประโยค','I am a student. I am Thai. I am happy. I am at home.');
a('04.03','รูปย่อช่วยให้การพูดและเขียนไม่เป็นทางการเป็นธรรมชาติ I am → I’m; you are → you’re; he is → he’s ใช้ apostrophe แทนตัวที่ละ ปฏิเสธเติม not หลัง be: I am not; she is not/isn’t; they are not/aren’t รูป I’m not เป็นรูปพื้นฐาน ไม่ใช้ I amn’t ในอังกฤษมาตรฐานทั่วไป','I’m ready. / I’m not ready.~บอกเล่า / ปฏิเสธ||She’s here. / She isn’t here.~she is / she is not||They’re busy. / They aren’t busy.~they are / they are not','its บอกเจ้าของ ต่างจาก it’s ที่ย่อ it is หรือ it has ตามโครงสร้าง',q('รูปย่อของ they are คืออะไร?','their|they’re|there',1,'they’re = they are; their เป็นคำบอกเจ้าของ'),q('ข้อใดเป็นปฏิเสธที่ถูก?','I amn’t late.|I’m not late.|I don’t late.',1,'I’m not = I am not'),'เปลี่ยนประโยค I am tired / She is busy / We are ready เป็นรูปย่อและปฏิเสธ','I’m tired → I’m not tired. She’s busy → She isn’t busy. We’re ready → We aren’t ready.');
a('04.04','คำถาม yes/no ด้วย be ย้าย be ไว้หน้าประธาน: You are ready → Are you ready? คำตอบสั้นใช้ pronoun + be ให้ตรงผู้ตอบ Yes, I am. / No, I’m not. ไม่ใช้ do/does ร่วมกับ be รูปนี้ และคำตอบบอกเล่าสั้นท้ายประโยคไม่ย่อเหลือ Yes, I’m','Is she here? — Yes, she is.~ถามและตอบเกี่ยวกับเธอ||Are they ready? — No, they aren’t.~ถามหลายคน||Are you a student? — Yes, I am.~เปลี่ยน you เป็น I เมื่อตอบ','Do you are ready? ผิด เพราะ be เป็นกริยาที่สลับหน้าได้เอง',q('เลือกคำถามที่ถูก','Do she is here?|Is she here?|Is she are here?',1,'คำถามใช้ Is + subject'),q('Are you ready? คำตอบสั้นบอกเล่าคืออะไร?','Yes, I’m.|Yes, I am.|Yes, you is.',1,'คำตอบเปลี่ยน you เป็น I และไม่ย่อ am ท้ายประโยค'),'ถามเพื่อนสามคำถามด้วย be และตอบทั้ง yes/no','Are you tired? No, I’m not. Is Ben here? Yes, he is. Are the books new? Yes, they are.');
a('04.05','วางคำถามหน้าประโยคก่อน be เช่น Where are you? What is your name? Who is she? How old are you? เลือกตามข้อมูลที่ต้องการ คำถามเกี่ยวกับสภาพใช้ How are you? ส่วน impersonal it ช่วยบอกเวลาและอากาศโดยไม่มีคนหรือสิ่งเฉพาะ เช่น It is cold. ไม่ละประธาน it','Where is Mai? — She is at home.~ถามตำแหน่ง||How old are you? — I am twenty.~ถามอายุ||What time is it? — It is nine.~it สำหรับเวลา','อายุอังกฤษใช้ be: I am twenty. ไม่แปลตรงเป็น I have twenty years ในรูปพื้นฐาน',q('ต้องการถามตำแหน่งของกระเป๋า ใช้คำใด?','Who is the bag?|Where is the bag?|How old is the bag?',1,'Where ถามสถานที่'),q('ข้อใดบอกอายุถูก?','I am eighteen.|I have eighteen.|I eighteen.',0,'ใช้ am เชื่อมกับอายุ'),'เขียนคำถามเกี่ยวกับชื่อ อายุ ที่อยู่และอากาศ แล้วตอบจากข้อมูลของคุณ','What is your name? My name is Mai. How old are you? I am twenty. Where are you? I am at home. Is it hot? Yes, it is.');
a('05.01','a/an ใช้กับคำนามนับได้เอกพจน์เมื่อกล่าวถึงหนึ่งหน่วยหรือสมาชิกหนึ่งประเภท เช่น a book, an apple คำนามนับได้เอกพจน์ทั่วไปไม่ยืนเดี่ยวในประโยคแบบ I have book ต้องมี determiner เช่น a/the/my/this ไม่ใช้ a/an หน้าพหูพจน์หรือคำนามนับไม่ได้ในความหมายทั่วไป','I have a book.~หนึ่งเล่มที่ยังไม่ระบุเล่ม||She is a doctor.~สมาชิกของอาชีพ doctor||I have books.~หลายเล่ม ไม่ใช้ a','a ไม่ได้แปลว่าเลขหนึ่งแบบเน้นจำนวนทุกครั้ง ใช้จัดสมาชิกหนึ่งประเภทได้',q('เลือกกลุ่มคำนามที่ถูก','a books|a book|a rice ในความหมายข้าวทั่วไป',1,'a ใช้กับ countable singular'),q('ประโยคใดถูก?','She is nurse.|She is a nurse.|She is a nurses.',1,'อาชีพ nurse เป็นคำนามนับได้เอกพจน์'),'เขียนของในกระเป๋าสามชนิดด้วย a/an และของหลายชิ้นหนึ่งประโยค','I have a pen, a book and an umbrella. I have pencils.');
a('05.02','เลือก a/an จากเสียงแรกของคำถัดไป ไม่ใช่ตัวอักษร an ใช้ก่อนเสียงสระ เช่น an apple, an hour เพราะ h ใน hour เงียบ a ใช้ก่อนเสียงพยัญชนะ เช่น a university เพราะเริ่ม /j/ เหมือน y และ a useful book ถ้ามี adjective ให้ฟังเสียงต้นของ adjective นั้น','an hour~h เงียบ เริ่มด้วยเสียงสระ||a university~เริ่มเสียง /j/||an old bag~เสียงต้น old เป็นสระ','an university ผิดในเสียงมาตรฐานทั่วไป และ a hour ผิดแม้เห็น h เป็นพยัญชนะ',q('เลือก article: … honest person','a|an|the เท่านั้น',1,'honest เริ่มเสียงสระเพราะ h เงียบ'),q('เลือก article: … useful tool','a|an|ไม่มี article เสมอ',0,'useful เริ่ม /j/ ซึ่งเป็นเสียงพยัญชนะ'),'อ่านกลุ่มคำ hour, university, apple, useful book และเติม a/an โดยให้เหตุผลจากเสียง','an hour; a university; an apple; a useful book.');
a('05.03','the ใช้เมื่อผู้พูดและผู้ฟังระบุสิ่งเดียวกันได้ เช่นกล่าวถึงไปแล้ว มีคำขยายระบุชัด หรือมีเพียงสิ่งเดียวที่เกี่ยวข้องในบริบท I see a dog. The dog is black. ครั้งแรกยังไม่รู้ว่าตัวไหนจึงใช้ a; ครั้งต่อมาอ้างกลับตัวเดิมใช้ the ใช้ the ได้กับเอกพจน์ พหูพจน์และนับไม่ได้ถ้าเฉพาะเจาะจง','I bought a book. The book is good.~ครั้งแรก / อ้างเล่มเดิม||Please close the door.~ประตูที่เข้าใจร่วมกัน||The water in this bottle is cold.~น้ำเฉพาะขวดนี้','the ไม่ได้แปลว่าคำนามมีหนึ่งเดียวในโลกเสมอ แต่ต้องระบุได้ในบริบท',q('I saw a cat. … cat was white.','A|An|The',2,'อ้างกลับแมวตัวที่เพิ่งกล่าวถึง'),q('เหตุใด the door จึงใช้ได้ในห้องหนึ่ง?','ผู้พูดและผู้ฟังระบุประตูได้|door เป็นพหูพจน์|door ต้องใช้ the ทุกครั้ง',0,'บริบททำให้รู้ว่าประตูไหน ไม่ใช่กฎว่า door ต้องมี the'),'เขียนเรื่องสองประโยคที่เริ่มด้วย a/an แล้วอ้างสิ่งเดิมด้วย the','I have an umbrella. The umbrella is blue.');
a('05.04','ไม่ใช้ article เมื่อกล่าวทั่วไปด้วยพหูพจน์หรือนับไม่ได้ เช่น Dogs are friendly. Water is important. ชื่อคน เมือง ภาษา และประเทศส่วนใหญ่มักไม่มี article เช่น Mai, Bangkok, English, Thailand แต่ชื่อบางกลุ่มมี the เช่น the United States ตรวจเป็นชื่อเต็ม ถ้าเจาะจงกลุ่มหรือน้ำที่รู้ว่าหมายถึงไหนยังใช้ the ได้','I like cats.~ชอบแมวทั่วไป||The cats in this room are quiet.~แมวเฉพาะในห้อง||She speaks English.~ชื่อภาษาไม่ใช้ the','ไม่ใช้กฎว่า plural ห้ามมี the; ความเฉพาะเจาะจงเป็นตัวตัดสิน',q('กล่าวถึงกาแฟทั่วไป เลือกประโยค','Coffee is popular.|The coffee is popular. หมายถึงกาแฟทั่วไปเสมอ|A coffee is popular. หมายถึงกาแฟทั่วไปเสมอ',0,'Coffee ไม่มี article เมื่อกล่าวทั่วไปในความหมาย uncountable'),q('ชื่อใดใช้ the ในชื่อมาตรฐาน?','Thailand|Bangkok|the United States',2,'the United States เป็นชื่อประเทศที่ใช้ the'),'เขียนความชอบทั่วไปสองประโยคและข้อมูลเมืองหรือภาษาอีกสองประโยค','I like books. Music is important to me. I live in Bangkok. I study English.');
a('05.05','กลุ่มคำนามพื้นฐานเรียง determiner + adjective + noun เช่น my blue bag หรือ a small room adjective อยู่หน้าคำนามในกลุ่มนี้ ไม่วาง article ซ้อนกับ my/this ที่ทำหน้าที่ determiner อยู่แล้ว เขียน my bag ไม่ใช่ the my bag ถ้าคำนามหลายชิ้นเปลี่ยน noun เป็น plural แต่ adjective ไม่เติม s','a small room~a + adjective + noun||my blue bags~my + adjective + plural noun||these new books~ชี้หลายเล่ม','a my book และ the this room ผิด; เลือก determiner ที่ตรงความหมายเพียงแบบหนึ่งในรูปพื้นฐานนี้',q('เลือกกลุ่มคำนามที่ถูก','the my red bag|my red bag|red my bag',1,'my ทำหน้าที่ determiner แล้วตามด้วย adjective และ noun'),q('เลือกกลุ่มของหลายเล่ม','these new books|these news books|new these books',0,'adjective new ไม่เติม s'),'บรรยายสิ่งของสี่กลุ่มโดยสลับใช้ a, my, this, these','a small cup; my blue bag; this old book; these new shoes.');
a('05.06','article เปลี่ยนจุดเน้น a book หมายถึงหนึ่งเล่มที่ยังไม่ระบุ; the book คือเล่มที่ระบุได้; books อาจกล่าวทั่วไป บางวลีใช้ตามกิจกรรมหรือจุดประสงค์ เช่น go to school คือไปเรียน ส่วน go to the school คือไปอาคารโรงเรียนที่ระบุได้ go home ไม่ใช้ to/the; in bed หมายถึงอยู่บนเตียงพักหรือนอนตามบริบท','I go to school.~ไปเรียน||I go to the school to meet a teacher.~ไปโรงเรียนแห่งที่ระบุเพื่อพบครู||I go home.~กลับบ้าน ไม่ใช้ to home','จำวลีพร้อมความหมาย อย่าเติมหรือถอด the ทุกครั้งจากชนิดสถานที่เพียงอย่างเดียว',q('ประโยคใดเป็นวลีกลับบ้านพื้นฐาน?','I go to home.|I go home.|I go to the home. เสมอ',1,'home เป็นคำบอกทิศทางในวลี go home'),q('go to school ต่างจาก go to the school อย่างไร?','อย่างแรกเน้นไปเรียน อย่างหลังระบุอาคารหรือสถานที่|ไม่ต่างกันได้เลย|อย่างแรกเป็นอดีต',0,'article สะท้อนการกล่าวถึงกิจกรรมกับสถานที่เฉพาะ'),'เขียนสองประโยคแยกการไปเรียนกับการไปอาคารโรงเรียน และหนึ่งประโยคกลับบ้าน','I go to school every day. My father goes to the school to meet my teacher. I go home after class.');
a('06.01','this/that ใช้กับสิ่งเดียว ส่วน these/those ใช้กับหลายสิ่ง this/these มักชี้ใกล้ผู้พูด; that/those มักชี้ไกลหรือสิ่งที่กำลังกล่าวถึง จับคู่ this/that กับ is และ these/those กับ are ใช้หน้าคำนามได้ เช่น this bag หรือแทนคำนามได้ เช่น This is mine.','This bag is blue.~ใกล้ หนึ่งใบ||Those bags are red.~ไกล หลายใบ||These are books.~ใช้แทนคำนามในตำแหน่งประธาน','ไม่ใช้ these bag หรือ this bags ในความหมายทั่วไป ต้องให้คำชี้และจำนวนตรงกัน',q('ของหลายชิ้นอยู่ใกล้ผู้พูด ใช้คำใด?','this|these|that',1,'these ชี้หลายสิ่งใกล้ผู้พูด'),q('เลือกประโยคที่ถูก','Those books is new.|Those book are new.|Those books are new.',2,'those กับ books เป็นพหูพจน์จึงใช้ are'),'ชี้สิ่งใกล้และไกลอย่างละหนึ่งกับหลาย แล้วเขียนสี่ประโยค','This pen is blue. These pens are blue. That bag is red. Those bags are red.');
a('06.02','my/your/his/her/its/our/their อยู่หน้าคำนามเพื่อบอกเจ้าของ จับคู่ I→my, you→your, he→his, she→her, it→its, we→our, they→their รูปไม่เปลี่ยนตามจำนวนสิ่งของ เช่น my book/my books its ไม่มี apostrophe ส่วน it’s ย่อ it is หรือ it has ตามโครงสร้าง','I have a bag. My bag is blue.~I ประธาน; my หน้าคำนาม||They have a room. Their room is small.~their บอกเจ้าของ||The dog moves its tail.~its บอกส่วนของสัตว์','ไม่ใช้ I bag แทน my bag; her + noun เป็นคำบอกเจ้าของ ต่างจาก her ที่เป็นกรรม',q('We have a house. … house is small.','Our|Us|We',0,'our ใช้หน้าคำนามบอกเจ้าของของ we'),q('ข้อใดบอกเจ้าของถูก?','It’s tail|Its tail|It tail',1,'its เป็นคำบอกเจ้าของ ไม่มี apostrophe'),'เขียนประธานแล้วเปลี่ยนเป็นคำบอกเจ้าของสามคู่','I → my phone; she → her book; they → their car.');
a('06.03','mine/yours/his/hers/ours/theirs แทนทั้งกลุ่มคำนามที่บอกเจ้าของ จึงไม่เติมคำนามตามหลัง my bag = mine ในบริบทที่รู้ว่าหมายถึงกระเป๋า his รูปเหมือนกันทั้งหน้าคำนามและแทนคำนาม แต่ her ต้องเปลี่ยนเป็น hers เมื่อใช้เดี่ยว ๆ','This is my bag. This bag is mine.~mine แทน my bag||That is her book. That book is hers.~hers ไม่มี noun ตาม||These seats are ours.~ours แทนที่นั่งของเรา','mine bag และ her’s ผิดในรูปนี้; possessive pronouns ไม่มี apostrophe',q('This is their room. This room is …','their|theirs|them',1,'theirs แทน their room'),q('เลือกประโยคที่ถูก','The pen is hers.|The pen is her’s.|The pen is her.',0,'hers เป็น possessive pronoun ไม่มี apostrophe'),'เขียนสามคู่ my/mine, her/hers, our/ours โดยไม่พูดคำนามซ้ำ','This is my cup. It is mine. That is her bag. It is hers. This is our room. It is ours.');
a('06.04','ใช้ชื่อเจ้าของ + ’s เช่น Anna’s bag ถ้าเจ้าของพหูพจน์ลง s ใช้ apostrophe หลัง s เช่น my parents’ room แต่ plural ที่ไม่ลง s ใช้ ’s เช่น children’s books รูป s มีสามหน้าที่ที่ต้องดูบริบท: books หลายเล่ม; Anna’s book ของ Anna; Anna’s happy ย่อ Anna is happy','Anna’s bag~กระเป๋าของ Anna||my parents’ room~ห้องของพ่อแม่หลายคน||children’s books~หนังสือของเด็กหลายคน','อย่าใช้ apostrophe เพื่อทำพหูพจน์ธรรมดา เช่น two book’s ผิด',q('ห้องของพ่อแม่ทั้งสองคน ใช้รูปใด?','my parents’ room|my parent’s room|my parents room',0,'parents เป็น plural ลง s จึงใส่ apostrophe หลัง s'),q('หนังสือของเด็กหลายคน ใช้รูปใด?','childrens’ books|children’s books|children books',1,'children เป็น plural ที่ไม่ลง s เติม ’s'),'แยก s ใน Ben’s here, Ben’s books และ two books แล้วเขียนรูปเจ้าของหนึ่งตัวอย่าง','Ben’s here = Ben is here; Ben’s books = หนังสือของ Ben; books = หลายเล่ม. My sister’s phone is new.');
a('06.05','Whose ถามเจ้าของและใช้หน้าคำนามหรือใช้เดี่ยวตามบริบท เช่น Whose bag is this? ตอบ It is Mai’s. / It is hers. วลี a friend of mine หมายถึงเพื่อนคนหนึ่งของฉัน ต่างจาก my friend ที่อาจชี้เพื่อนเฉพาะ ใช้ of + possessive pronoun เช่น of theirs ไม่ใช้ of they','Whose book is this? — It is Ben’s.~ถามเจ้าของ||She is a friend of mine.~เพื่อนคนหนึ่งของฉัน||He is a friend of theirs.~เพื่อนคนหนึ่งของพวกเขา','Who’s = who is/who has ต่างจาก Whose ที่ถามเจ้าของ',q('คำใดถามเจ้าของ?','Who’s|Whose|Where',1,'Whose ถามว่าเป็นของใคร'),q('เลือกวลีที่ถูก','a friend of my|a friend of I|a friend of mine',2,'หลัง of ในโครงนี้ใช้ possessive pronoun mine'),'ถามเจ้าของสิ่งของสองชิ้นและแนะนำเพื่อนคนหนึ่งของคุณ','Whose pen is this? It is Mai’s. Whose bag is that? It is his. Ben is a friend of mine.');
a('07.01','adjective บรรยาย noun ได้สองตำแหน่งพื้นฐาน: ก่อน noun เช่น a small room หรือหลัง be เช่น The room is small. รูป adjective ไม่เปลี่ยนตามจำนวนคำนาม small rooms ไม่ใช่ smalls rooms ถ้า adjective เป็นสภาพของประธานต้องมี be ไม่ใช้ The room small. เป็นประโยคเต็ม','a blue bag / blue bags~blue ไม่เติม s||The bag is blue. / The bags are blue.~be เปลี่ยนตามจำนวน แต่ blue คงเดิม','adjective ไม่ใช่กริยาการกระทำ จึงต้องเลือกโครงสร้างให้เหมาะ',q('เลือกกลุ่มคำนามที่ถูก','reds bags|red bags|bags red ใน noun phrase พื้นฐาน',1,'red อยู่ก่อน bags และไม่เติม s'),q('เลือกประโยคเต็ม','The rooms small.|The rooms are small.|The rooms is smalls.',1,'rooms หลายห้องใช้ are; small คงรูป'),'บรรยายสิ่งของสามอย่างทั้งรูปกลุ่มคำนามและประโยค','a red cup → The cup is red. new shoes → The shoes are new. a small desk → The desk is small.');
a('07.02','เลือก adjective ให้ตรงคุณลักษณะที่สังเกต สี red/blue; ขนาด big/small; รูปร่าง round/square; อายุ new/old; สัญชาติ Thai/Japanese; บุคลิก kind/friendly; สภาพ clean/dirty คำหนึ่งอาจมีความหมายตามบริบท เช่น old ใช้กับอายุคนหรือสิ่งของเก่า และ new หมายถึงใหม่ต่อผู้พูดได้','a round table~โต๊ะทรงกลม||a friendly teacher~ครูที่เป็นมิตร||The room is clean.~ห้องสะอาด','สัญชาติขึ้นต้นตัวใหญ่ แต่สีทั่วไปไม่ต้องขึ้นต้นใหญ่กลางประโยค',q('ต้องการบอกโต๊ะทรงกลม เลือกคำใด?','round|friendly|Thai',0,'round บอก shape'),q('ข้อใดบอกบุคลิก?','a blue teacher|a friendly teacher|a square teacher',1,'friendly เป็นคำบอกบุคลิกในบริบทคน'),'เลือกสิ่งของหนึ่งชิ้นและคนหนึ่งคน บรรยายอย่างละสองคุณลักษณะ','My table is small and round. My teacher is kind and friendly.');
a('07.03','เมื่อมีหลาย adjective ให้เริ่มจากชุดที่ใช้บ่อย เช่น size + colour + noun: a small blue bag ลำดับมักให้ความคิดเห็นมาก่อนขนาดและคุณสมบัติเฉพาะ เช่น a lovely small red bag ไม่ต้องท่องตารางยาวก่อนใช้ แต่สังเกตกลุ่มคำและตรวจตัวอย่างจริงเมื่อมีหลายคำมาก','a small blue bag~ขนาดก่อนสี||a big round table~ขนาดก่อนรูปร่าง||a lovely red dress~ความเห็นก่อนสี','ไม่ย้าย noun ไปกลางชุด adjective และไม่เติม article แยกทุกคำเมื่อพูดถึงสิ่งเดียว',q('เลือกกลุ่มคำนามธรรมชาติในบทนี้','a blue small bag|a small blue bag|a small bag blue',1,'ขนาด small ก่อนสี blue แล้วจบด้วย noun'),q('a big round … ควรตามด้วยอะไร?','table|a|big',0,'table เป็น noun ที่ถูกบรรยาย'),'บรรยายสามสิ่งโดยใช้ adjective สองคำต่อ noun','a small black phone; a big round table; a lovely blue shirt.');
a('07.04','adjective ลง -ed มักบอกความรู้สึกผู้ได้รับผล เช่น I am bored. ส่วน -ing บอกสิ่งหรือคนที่ทำให้เกิดความรู้สึก เช่น The lesson is boring. ใช้คู่ interested/interesting, excited/exciting ตามความหมาย รูปเหล่านี้เป็น adjective ได้ จึงอย่าคิดว่า -ing ทุกคำคือ Present Continuous','I am interested in music.~ฉันสนใจดนตรี||Music is interesting.~ดนตรีน่าสนใจ||She is bored. The film is boring.~เธอเบื่อ / หนังทำให้เบื่อ','I am boring. หมายถึงฉันทำให้คนอื่นเบื่อ ซึ่งต่างจาก I am bored.',q('คุณรู้สึกตื่นเต้นก่อนเดินทาง: I am …','excited|exciting|excite',0,'excited บอกความรู้สึกของผู้พูด'),q('หนังทำให้คนดูสนใจ: The film is …','interested|interesting|interest',1,'interesting บอกคุณสมบัติที่ทำให้สนใจ'),'เขียนสองคู่เกี่ยวกับความรู้สึกของคุณกับสิ่งที่ทำให้รู้สึก','I am excited. The trip is exciting. I am interested in art. Art is interesting.');
a('07.05','รวม adjective กับ noun phrase เพื่อบรรยายให้เฉพาะเจาะจง I am happy. บอกสภาพตอนนี้ ส่วน I am a happy person. บรรยายลักษณะบุคคลโดยรวม คำถาม What is Ben like? ขอคำบรรยายบุคลิกหรือคุณลักษณะ ต่างจาก What does Ben like? ที่ถามความชอบ','What is Mai like? — She is kind.~ถามบุคลิก||What is the room like? — It is small and bright.~ถามลักษณะ||I am happy. / I am a happy person.~สภาพ / ลักษณะบุคคล','like ใน What is … like? ไม่ได้เป็นกริยาชอบในโครงสร้างนี้',q('What is your teacher like? คำตอบใดตรงคำถาม?','She is friendly.|She likes tea.|She is at school.',0,'คำถามขอคำบรรยายลักษณะหรือบุคลิก'),q('เลือกประโยคที่มีกลุ่มคำนามบรรยายบุคคล','I am a kind person.|I am a kind.|I am person kind.',0,'a + adjective + noun จัดเป็น noun phrase'),'บรรยายคนหนึ่งคนและห้องหนึ่งห้อง แล้วตั้งคำถาม What is … like?','What is Ben like? He is a friendly person. What is his room like? It is small and clean.');
a('08.01','เรียนกริยาพร้อมสิ่งที่ใช้ร่วมกัน go to school, come home, live in Bangkok, work in a shop, study English, eat rice, drink water, like music, want a book กลุ่มคำช่วยให้ใช้ถูกมากกว่าท่องคำแปลเดี่ยว ๆ ใน Present Simple I/you/we/they ใช้รูปพื้นฐาน; he/she/it จะเปลี่ยนรูปในบทถัดไป','I live in Bangkok.~live in + สถานที่||We study English.~study + วิชาหรือภาษา||I drink water.~drink + สิ่งที่ดื่ม','ไม่เติม to หลังกริยาทุกคำ เช่น study English ไม่ใช่ study to English',q('เลือกกลุ่มคำที่ถูก','study to English|study English|study at English',1,'study รับกรรมชื่อวิชาโดยตรง'),q('ต้องการบอกที่อยู่อาศัย เลือก','I live in Chiang Mai.|I eat Chiang Mai.|I drink Chiang Mai.',0,'live in ใช้กับสถานที่อาศัย'),'เขียนกิจกรรมของคุณห้าประโยคด้วยกริยาต่างกัน','I live in Bangkok. I study English. I eat rice. I drink water. I like music.');
a('08.02','กริยาหนึ่งคำมีหลายรูป เช่น work/works/working/worked/worked และ go/goes/going/went/gone รูปพื้นฐาน V1 ใช้หลัง I ใน Present Simple; s-form ใช้กับ he/she/it; -ing ใช้ใน continuous พร้อม be; V2 ใช้เล่าอดีต; V3 ใช้หลัง have หรือใน passive ภายหลัง เวลาในความหมายกับ tense ไม่ใช่สิ่งเดียวกัน เช่น Present Simple ใช้กับตารางอนาคตได้','go — goes — going — went — gone~รูปต่างกันตามโครงสร้าง||work — works — working — worked — worked~V2 และ V3 เหมือนกัน','ตอนนี้รู้หน้าที่คร่าว ๆ ไม่ต้องเอาทุกรูปมาต่อกัน และอย่าคิดว่าคำเวลาอนาคตบังคับ will เสมอ',q('รูปไหนเป็น base form ของ eat?','eats|eat|eaten',1,'eat เป็นรูปพื้นฐาน; eats เป็น s-form; eaten เป็น V3'),q('V2 และ V3 ของ work เป็นอย่างไร?','เหมือนกัน: worked|ต่างกันทุกครั้ง|ไม่มีรูป V3',0,'regular verbs มักมี V2/V3 ลง ed เหมือนกัน'),'ทำบัตรรูปกริยา go และ work พร้อมจดว่าจะกลับมาใช้ V2/V3 ในบทใด','go/goes/going/went/gone; work/works/working/worked/worked. V2 ใช้ใน M20 และ V3 ใช้ใน M25/M31.');
a('08.03','Present Simple ใช้กับกิจวัตร ข้อเท็จจริงทั่วไปและสภาพที่คงอยู่ในความหมายที่พูด เช่น I work in a shop. ไม่ได้แปลว่ากำลังทำงาน ณ วินาทีนี้เสมอ ข้อมูลอย่าง Water boils at 100°C ใช้ข้อเท็จจริงทั่วไปภายใต้ความดันบรรยากาศปกติ คำบอกกิจวัตรช่วยบริบท แต่การเลือก tense ต้องดูความหมายของทั้งข้อความ','I study English every day.~กิจวัตร||She lives in Chiang Mai.~สภาพที่เป็นจริงในช่วงนี้||Birds have wings.~ข้อเท็จจริงทั่วไป','สิ่งกำลังเกิด ณ ตอนนี้จะใช้ Present Continuous ใน M17; ไม่เลือก tense จากคำใบ้หนึ่งคำโดยไม่ดูความหมาย',q('I walk to school every day สื่ออะไรเป็นหลัก?','กิจวัตร|เหตุการณ์ที่จบเมื่อวาน|คำสั่ง',0,'every day บอกการทำเป็นปกติ'),q('ข้อใดเป็นข้อเท็จจริงทั่วไป?','Cats are animals.|I went home yesterday.|I am running now.',0,'Cats are animals ใช้ปัจจุบันบอกประเภททั่วไป'),'เขียนกิจวัตรสองข้อและข้อเท็จจริงหนึ่งข้อ','I eat breakfast every day. I study English. Dogs are animals.');
a('08.04','I/you/we/they กับ Present Simple บอกเล่าใช้ base verb เช่น I work. We study. ไม่ต้องมี am/are นำหน้า เพราะ work/study เป็นกริยาอยู่แล้ว เปรียบเทียบ I am happy. ที่ happy เป็น adjective ต้องมี be ประธานหลายคนเช่น My friends ใช้รูปพื้นฐานเช่นเดียวกับ they','I work in a shop.~กริยาทั่วไปไม่เติม am||We study English.~we + base verb||I am happy.~adjective ใช้ be','I am work และ We are study ผิดใน Present Simple; หากกำลังทำจะต้องเป็น am working/are studying ตามบท M17',q('เลือก Present Simple ที่ถูก','They are play football.|They play football.|They plays football.',1,'they ใช้ base verb play'),q('ประโยคใดต้องมี am?','I … happy.|I … drink water.|I … read books.',0,'happy เป็น adjective; drink/read เป็น verb'),'เขียนสี่ประโยคด้วย I, you, we, they และเปรียบเทียบหนึ่งประโยคด้วย be','I read. You work. We study. They walk. I am ready.');
a('08.05','he/she/it และประธานเอกพจน์ใน Present Simple บอกเล่าเติม s/es ให้กริยา ส่วนใหญ่เติม s; ลง sh/ch/s/x/o บางคำเติม es เช่น watches/goes/does; พยัญชนะ + y เปลี่ยนเป็น ies เช่น studies แต่ plays เติม s เสียงท้ายมี /s,z,ɪz/ เหมือนพหูพจน์ noun แต่หน้าที่ต่างกัน','Mai works. / My friends work.~ประธานหนึ่ง / หลาย||She studies. / He plays.~study → studies; play → plays||He watches TV.~เติม es','ใน She likes books, likes เป็น verb agreement ส่วน books เป็น plural noun; อย่าเติม s ให้กริยาตามจำนวนกรรม',q('My brother … English.','study|studies|studys',1,'brother เอกพจน์ และ study มีพยัญชนะหน้า y จึง studies'),q('เลือกประโยคที่ถูก','She like books.|She likes books.|She liking books.',1,'She ใช้ likes; books หลายเล่มเป็นกรรม'),'เปลี่ยน I go / I study / I play / I watch เป็นประโยคเกี่ยวกับ Mai','Mai goes to school. Mai studies English. Mai plays football. Mai watches TV.');
a('08.06','have/has เป็นกริยาทั่วไปเมื่อบอกการมี: I have a bike; she has a bike ใช้ have ในกิจกรรมบางกลุ่มเช่น have breakfast จึงไม่ได้แปลว่าครอบครองทุกครั้ง have got เป็นรูปบอกการมีที่พบบ่อยใน British English: I have got / she has got ใช้คำถาม Have you got…? ต่างจาก Do you have…? รูปปฏิเสธคือ I haven’t got / she hasn’t got อย่าปนสองระบบในประโยคเดียว','I have a bike. / She has a bike.~have/has ตามประธาน||I have breakfast at seven.~have เป็นกิจกรรมกิน||Have you got a pen? — Yes, I have.~have got แบบบอกการมี','ไม่เขียน Does she has…? หลัง does ใช้ have; Have you got…? ไม่เติม do อีก',q('Ben … two sisters.','have|has|haves',1,'Ben เอกพจน์ใช้ has'),q('เลือกคำถามถูกเกี่ยวกับการมี','Do you have a pen?|Do you have got a pen?|Does you has a pen?',0,'Do you have…? ใช้ระบบกริยาทั่วไป; Have you got…? เป็นอีกระบบ'),'บอกสิ่งที่คุณมีสองประโยคและกิจกรรมหนึ่งประโยคด้วย have แล้วเขียน have got อีกแบบ','I have a phone. I have two books. I have breakfast at home. I have got a phone.');
a('08.07','ขยายประโยคโดยเพิ่มกรรม เวลาและสถานที่ตามข้อมูลที่ต้องการ เช่น My sister reads books at home. ดูจำนวนประธานจากกลุ่มคำนาม My sister หนึ่งคนจึง reads ไม่เปลี่ยนตามจำนวนกรรม books ลำดับพื้นฐาน subject + verb + object + place/time ช่วยเริ่มได้ แต่ข้อมูลเวลาอาจอยู่ต้นประโยคตามจุดเน้น','My sister reads books at home.~ประธานหนึ่ง กรรมหลาย||My sisters read books at home.~ประธานหลาย||Every day, Ben walks to school.~เวลาอยู่ต้นได้','เติม s ตาม subject ไม่ใช่คำที่อยู่ชิด verb โดยไม่ดูหน้าที่',q('The students … English at school.','studies|study|studys',1,'students เป็น plural จึง study'),q('ใน She reads books at home จำนวน books กำหนด reads หรือไม่?','ไม่กำหนด ประธาน She กำหนด|กำหนดเพราะอยู่หลังกริยา|ทำให้ต้องใช้ read',0,'agreement ดูประธาน She'),'ขยาย I read ให้มีสิ่งที่อ่าน สถานที่และเวลา แล้วเปลี่ยนประธานเป็นเพื่อนคนหนึ่ง','I read books at home every day. Ben reads books at home every day.');
a('09.01','กรรมใช้ me/you/him/her/it/us/them แทนกลุ่มคำนามหลัง verb เปรียบเทียบ I like him. กับ He likes me. รูปขึ้นกับหน้าที่ ไม่ใช่เพศหรือความหมายภาษาไทยอย่างเดียว I/he/she/we/they เป็น subject; me/him/her/us/them เป็น object ส่วน you/it รูปเหมือนกัน','She helps me.~She ประธาน; me กรรม||I help her.~I ประธาน; her กรรม||We know them.~them แทนคนหลายคน','Him likes I ผิดทั้งสองตำแหน่ง ให้ใช้ He likes me.',q('Ben helps … (ฉัน)','I|my|me',2,'ตำแหน่งหลัง helps เป็นกรรม ใช้ me'),q('เลือกประโยคที่ถูก','They know us.|Them know we.|Their know our.',0,'They ประธาน; us กรรม'),'แต่งประโยคสามคู่โดยสลับผู้ทำกับผู้รับ','I help her. She helps me. We know them. They know us.');
a('09.02','หลัง preposition เช่น with/for/to ใช้ object pronouns: with me, for her, to them รูป I/she/they ไม่ใช้ในตำแหน่งนี้ คำบุพบทบอกความสัมพันธ์ เช่นไปด้วยกัน with, ทำให้ for, ส่งถึง to ต้องเรียนคำที่ใช้ร่วมกริยาด้วย','Come with me.~with + me||This gift is for her.~for + her||I talk to them.~to + them','with I และ for she ผิด แม้ภาษาไทยไม่เปลี่ยนรูปสรรพนาม',q('This letter is for … (เขาผู้ชาย)','he|him|his',1,'หลัง for ใช้ object pronoun him'),q('เลือกวลีที่ถูก','with they|with their|with them',2,'them เป็น object pronoun หลัง preposition'),'เขียนคำชวนด้วย with, ของให้ใครด้วย for และคำพูดถึงใครด้วย to','Come with us. This book is for you. I talk to her.');
a('09.03','กริยา give/show/send ใช้สองกรรมได้: give me a book คือผู้รับ me แล้วสิ่งที่ให้ a book หรือ give a book to me คือสิ่งก่อนแล้วใช้ to บอกผู้รับ ส่วน buy/make ใช้ for ในรูปที่พบบ่อย เช่น buy a gift for her รูปเลือกตามกริยา ไม่เปลี่ยน to/for แบบอิสระทุกคำ','She gives me a book.~ผู้รับ + สิ่งของ||She gives a book to me.~สิ่งของ + to ผู้รับ||He buys a gift for her.~for ผู้ได้รับประโยชน์','ไม่ใช้ give me to a book; ถ้าเปลี่ยนรูปต้องรักษาผู้รับและสิ่งของให้ตรง',q('รูปใดเท่ากับ He sends me a letter?','He sends a letter to me.|He sends to a letter me.|He sends me to a letter.',0,'ย้ายสิ่งของ letter มาก่อนแล้วใช้ to me'),q('He buys a cake … us.','to|for|of',1,'buy something for someone ใช้ for ผู้ได้รับประโยชน์'),'เขียน give และ show อย่างละสองรูป แล้วเขียน buy … for …','I give Ben a pen. I give a pen to Ben. I show her a picture. I show a picture to her. I buy a book for him.');
a('09.04','pronouns ช่วยอ้างกลับโดยไม่พูดชื่อซ้ำ แต่ต้องมีบริบทชัด Mai has a bag. She likes it. She อ้าง Mai; it อ้าง bag ถ้าคำนามหลายชิ้นใช้ they เป็นประธานและ them เป็นกรรม เช่น The books are new. I like them. her อาจเป็นกรรมใน I help her หรือคำเจ้าของใน her bag ให้ดูว่ามี noun ตามหรือไม่','Ben has two dogs. They are small. He likes them.~They/them อ้าง dogs; He อ้าง Ben||I help her. / Her bag is blue.~her กรรม / her หน้าคำนาม','ถ้ามีคนหรือสิ่งหลายตัวที่อาจตรง pronoun ใช้ชื่อซ้ำเพื่อไม่ให้คนอ่านเดา',q('The shoes are new. I like …','it|they|them',2,'shoes เป็น plural และอยู่ตำแหน่งกรรม ใช้ them'),q('ใน Her phone is new คำ Her ทำหน้าที่ใด?','คำบอกเจ้าของหน้าคำนาม|ประธานเดี่ยว|กริยา',0,'มี noun phone ตามจึงเป็น possessive determiner'),'เขียนเรื่องสามประโยคที่อ้างคนและสิ่งของให้ชัด','Mai has a book. She reads it every day. Ben has two books. He likes them.');
a('10.01','Present Simple ปฏิเสธกริยาทั่วไปใช้ I/you/we/they + do not/don’t + base verb และ he/she/it + does not/doesn’t + base verb does รับรูปตามประธานแล้วกริยาหลักจึงไม่เติม s ไม่ใช้รูปนี้กับ be: She is not tired.','I don’t drink coffee.~don’t + base||She doesn’t drink coffee.~doesn’t + base||She isn’t tired.~be ใช้ not ตรงหลัง be','She doesn’t drinks ผิด; ต้องถอด s จากกริยาหลักเมื่อมี does',q('Ben … live here.','don’t|doesn’t|isn’t',1,'live เป็นกริยาทั่วไป; Ben เอกพจน์ใช้ doesn’t'),q('เลือกประโยคที่ถูก','She doesn’t works.|She doesn’t work.|She don’t work.',1,'doesn’t + base work'),'เขียนสิ่งที่คุณไม่ทำสองข้อ แล้วเขียนเกี่ยวกับเพื่อนสองข้อ','I don’t drink coffee. I don’t play tennis. Mai doesn’t eat meat. Ben doesn’t live here.');
a('10.02','ถาม yes/no กริยาทั่วไปใช้ Do/Does + subject + base verb? I/you/we/they ใช้ Do; he/she/it ใช้ Does คำตอบสั้นใช้ auxiliary เดิม: Yes, she does. / No, they don’t. คำถาม be ใช้ Is/Are โดยไม่เติม Do: Is she tired?','Do you like tea? — Yes, I do.~ผู้ตอบใช้ I||Does Ben work here? — No, he doesn’t.~does + work||Is Ben tired? — Yes, he is.~be แยกระบบ','Does he likes? ผิด และคำตอบ Yes, he is ไม่ตรง Does he like…?',q('เลือกคำถามที่ถูก','Does Mai study English?|Does Mai studies English?|Do Mai study English?',0,'Mai ใช้ Does ตามด้วย base study'),q('Do they live here? คำตอบสั้นปฏิเสธคืออะไร?','No, they aren’t.|No, they don’t.|No, they doesn’t.',1,'คำถาม Do ตอบด้วย don’t'),'ถามกิจวัตรสามคำถามและตอบทั้งบอกเล่ากับปฏิเสธ','Do you drink tea? Yes, I do. Does Mai play tennis? No, she doesn’t. Do your friends study here? Yes, they do.');
a('10.03','Wh-question กริยาทั่วไปใช้คำถาม + do/does + subject + base verb เช่น Where do you live? When does Ben work? what ถามสิ่ง; who คน; where ที่; when เวลา; why เหตุผล; how วิธี คำผสม What time ถามเวลาเฉพาะ What kind of ถามชนิด Why ตอบด้วย because ตามเหตุผล','Where do you live? — In Bangkok.~ถามที่||What time does she start? — At nine.~เวลาเฉพาะ||Why do you study English? — Because I like it.~เหตุผล','อย่าใช้ Where you live? ในรูปคำถามพื้นฐานที่กำลังฝึก ต้องมี do',q('ถามเหตุผลที่เขาเรียนภาษาอังกฤษ เลือก','Why does he study English?|Where does he study English?|Who studies English?',0,'Why ถามเหตุผล และ he ใช้ does + study'),q('เลือกคำถามเวลาเริ่มงาน','What time do you start work?|What kind of do you work?|What you time start?',0,'What time + do + subject + base verb'),'ถามและตอบสถานที่ เวลาและเหตุผลจากชีวิตของคุณ','Where do you live? In Chiang Mai. What time do you study? At eight. Why do you study? Because I like English.');
a('10.04','what ถามสิ่งหรือข้อมูลทั่วไป; which ถามตัวเลือกจากชุดที่มีอยู่; whose ถามเจ้าของ เช่น What book do you like? อาจถามกว้าง ส่วน Which book do you want, this one or that one? มีตัวเลือกชัด Whose book is this? ถามเจ้าของและใช้ be ตามโครงประโยค ไม่เติม do โดยอัตโนมัติ','What music do you like?~ถามชนิดหรือสิ่งทั่วไป||Which cup do you want, red or blue?~ถามเลือกจากชุด||Whose cup is this?~ถามเจ้าของ','เลือกคำถามจากข้อมูลที่ต้องการ ไม่แปล which เป็นคำว่าที่ทุกกรณี',q('มีเสื้อสองตัวให้เลือก คำถามเหมาะที่สุดคืออะไร?','Which shirt do you want?|Whose shirt do you want?|Where shirt do you want?',0,'which เลือกจากตัวเลือกที่ระบุ'),q('ต้องการรู้เจ้าของโทรศัพท์ ใช้คำใด?','What colour|Whose|When',1,'Whose ถามเป็นของใคร'),'เขียนคำถาม what/which/whose อย่างละหนึ่ง พร้อมตอบ','What food do you like? Rice. Which bag do you want, this one or that one? This one. Whose phone is this? It is Ben’s.');
a('10.05','ถ้าถามว่าใครเป็นผู้ทำ ใช้ Who + verb โดยไม่เติม do ในรูปบอกเล่าพื้นฐาน: Who works here? เพราะ Who เป็นประธาน แต่ถ้าถามว่าคุณช่วยใคร Who เป็นกรรม จึงใช้ Who do you help? คำตอบช่วยตรวจหน้าที่: Mai works here. / I help Mai.','Who helps Ben? — Mai helps Ben.~Who เป็นประธาน||Who do you help? — I help Ben.~Who เป็นกรรม||What happens?~What เป็นประธาน','ไม่ใช้ Who does works here? และไม่ตัด do จากคำถามกรรมโดยอัตโนมัติ',q('คำถามที่ตอบว่า Mai lives here คืออะไร?','Who lives here?|Who does lives here?|Who do live here?',0,'Who แทนผู้ทำ lives จึงเป็น subject question'),q('คำถามที่ตอบว่า I know Ben คืออะไร?','Who knows you?|Who do you know?|Who know?',1,'ถามกรรม Ben; ประธาน you ยังอยู่ จึงใช้ do'),'เขียนคำถามประธานและกรรมเกี่ยวกับ help อย่างละหนึ่ง แล้วตอบ','Who helps Mai? Ben helps Mai. Who does Mai help? Mai helps her brother.');
a('10.06','How…? ขอวิธีหรือสภาพ ส่วน What is … like? ขอคำบรรยาย ใช้คำถามต่อให้บทสนทนาไปได้ เช่น Who do you work with? preposition with อยู่ท้ายในภาษาทั่วไป คำถามสะท้อน Do you? / Does she? แสดงสนใจหรือขอให้เล่าต่อ ใช้ auxiliary ให้ตรงกริยาของประโยคที่ได้ยิน','How do you go to work? — By bus.~วิธีเดินทาง||Who do you study with? — With Ben.~with ท้ายคำถาม||I work in a shop. — Do you?~ถามต่อด้วย do','What is she like? ถามลักษณะ; What does she like? ถามความชอบ เป็นคนละข้อมูล',q('I like jazz. คำถามสะท้อนที่ตรง auxiliary คืออะไร?','Do you?|Are you?|Does you?',0,'like เป็นกริยาทั่วไปกับ I ใช้คำถามต่อ Do you?'),q('เลือกคำถามที่ถูก','Who do you work with?|Who with you work?|Who does you work with?',0,'Who + do + you + work + with'),'สร้างบทสนทนาสี่บรรทัดที่ตอบแล้วถามต่อด้วย How หรือ Who … with','I study English. — Do you? Who do you study with? — With Mai. — How do you study? — We read books.');
checkpoints[1]=cp([q('คู่ใดต่างที่พยัญชนะต้น r/l?','rice/light|ship/sheep|tea/tea',0,'rice เริ่ม /r/ และ light เริ่ม /l/; ย้อน 01.02'),q('silent e ปรากฏในคำใด?','bike|big|bus',0,'e ท้าย bike ไม่ออกเสียงและสัมพันธ์กับเสียง i; ย้อน 01.05'),q('teacher โดยทั่วไปมี stress ที่ใด?','พยางค์แรก|พยางค์ท้าย|ทุกพยางค์เท่ากัน',0,'TEAcher; ฟังพจนานุกรมตรวจ ย้อน 01.06')],'สะกดชื่อ อ่าน light/right, ship/sheep, book/books แล้วเลือกคำใหม่สองคำฟังตรวจเสียง บันทึกตนเองหนึ่งรอบ','My name is Mai. M–A–I. light/right; ship/sheep; book/books. คำใหม่ teacher และ about',['แยกชื่ออักษรกับเสียงคำ','คงเสียงท้ายและไม่เพิ่มสระแทรก','ตรวจ word stress ด้วยเสียงจริง']);
checkpoints[2]=cp([q('ใน My dog eats rice ประธานคืออะไร?','My dog|eats|rice',0,'กลุ่ม My dog เป็นผู้ทำ ย้อน 02.02'),q('ประโยคใดไม่ต้องมีกรรม?','The baby sleeps.|She puts.|I put.',0,'sleeps ใช้โดยไม่มีกรรมได้ ย้อน 02.03'),q('แก้ประโยคใดเป็นข้อมูลสภาพถูก?','He is cold.|He cold.|He is walks.',0,'cold เป็น adjective จึงใช้ is ย้อน 02.04')],'เขียนสองประโยคการกระทำและสองประโยคสภาพ พร้อมระบุ subject/verb/object หรือ complement','I eat rice. Birds fly. Ben is happy. His room is small.',['ทุกประโยคบอกเล่ามีประธานกับกริยา','แยกกรรมจากคำบรรยายประธาน','ใช้ตัวใหญ่และเครื่องหมายท้าย']);
checkpoints[3]=cp([q('Anna and I แทนด้วยอะไร?','we|they|she',0,'รวมผู้พูดใช้ we ย้อน 03.02'),q('one bus → two …','buss|buses|busies',1,'bus ลง s เติม es ย้อน 03.03'),q('ข้อใดเป็น plural ที่ถูก?','three womans|three women|three womens',1,'woman → women ย้อน 03.04')],'บรรยายรายการสิ่งของและคนที่มีหนึ่งกับหลาย แล้วใช้ pronouns อ้างกลับ','There is one child. There are two women and three books. They are here.',['เลือก plural ตรงจำนวน','ใช้รูปพิเศษไม่เติม s ซ้ำ','pronoun มีสิ่งที่อ้างกลับชัด']);
checkpoints[4]=cp([q('The chairs … new.','am|is|are',2,'chairs หลายตัวใช้ are ย้อน 04.01'),q('Are your friends Thai? — Yes, …','they are|they is|they’re',0,'คำตอบสั้นบอกเล่าไม่ย่อ be ท้าย ย้อน 04.04'),q('ถามอายุของ Ben ใช้รูปใด?','How old is Ben?|How old does Ben?|How Ben old?',0,'How old + is + Ben ย้อน 04.05')],'แนะนำตัวด้วยตัวตน สภาพและที่อยู่ จากนั้นถามเพื่อนสองคำถามและตอบ','I am Mai. I am Thai. I am ready. I am at home. Are you ready? Yes, I am. Where is Ben? He is at school.',['จับคู่ am/is/are','คำถามสลับ be กับประธาน','คำตอบสั้นใช้ pronoun และ be ตรงคำถาม']);
checkpoints[5]=cp([q('เลือกกลุ่มคำนามที่ถูก','an university|a university|a universities',1,'university เริ่มเสียง /j/ ย้อน 05.02'),q('I found a key. … key is small.','A|An|The',2,'อ้างกุญแจที่กล่าวแล้ว ย้อน 05.03'),q('ข้อใดกล่าวชอบสุนัขทั่วไป?','I like dogs.|I like the dogs. ทุกบริบท|I like a dogs.',0,'plural ทั่วไปไม่ใช้ article ย้อน 05.04')],'เล่าเรื่องสิ่งของหนึ่งชิ้นสามประโยค ใช้ a/an แล้ว the และบอกความชอบทั่วไปหนึ่งประโยค','I have an old bag. The bag is blue. My blue bag is small. I like bags.',['เลือก a/an ตามเสียง','อ้างสิ่งเดิมด้วย the','ไม่ซ้อน my กับ article']);
checkpoints[6]=cp([q('หลายสิ่งไกลผู้พูดใช้คำใด?','these|those|this',1,'those = plural ไกล ย้อน 06.01'),q('This is our classroom. It is …','our|ours|us',1,'ours แทนกลุ่มคำนาม ย้อน 06.03'),q('ข้อใดถามเจ้าของ?','Whose shoes are these?|Who’s shoes are these?|Who shoes these?',0,'Whose ถามเจ้าของ ย้อน 06.05')],'บรรยายสิ่งใกล้ไกลและเจ้าของสี่ประโยค ตั้งคำถาม Whose หนึ่งข้อ','This cup is mine. Those books are Ben’s. These pens are ours. That bag is hers. Whose phone is this?',['จำนวนตรง this/these','my/mine ใช้ตำแหน่งถูก','apostrophe ใช้บอกเจ้าของตามจำนวน']);
checkpoints[7]=cp([q('เลือกกลุ่มคำบรรยายถูก','two smalls rooms|two small rooms|two rooms small',1,'adjective ไม่เติม s ย้อน 07.01'),q('I feel … because the game is exciting.','excited|exciting|excite',0,'excited บอกความรู้สึก ย้อน 07.04'),q('What is your room like? คำตอบใดตรง?','It is big and clean.|I like coffee.|It likes me.',0,'ถามลักษณะของห้อง ย้อน 07.05')],'บรรยายคนกับสิ่งของอย่างละสองประโยคและแยกความรู้สึกจากสิ่งที่ทำให้รู้สึก','Mai is a kind person. Her room is small and bright. She is interested in art. Art is interesting.',['adjective อยู่ก่อน noun หรือหลัง be','ไม่เติม s ให้ adjective','เลือก ed/ing ตามผู้รู้สึกกับสิ่งที่ทำให้รู้สึก']);
checkpoints[8]=cp([q('My friend … to school.','go|goes|going',1,'friend หนึ่งคนใช้ goes ย้อน 08.05'),q('เลือก Present Simple ที่ถูก','We are eat rice.|We eat rice.|We eats rice.',1,'we + base eat ไม่ใส่ be ย้อน 08.04'),q('He … breakfast at home.','has|have|haves',0,'he ใช้ has; have breakfast เป็นกิจกรรม ย้อน 08.06')],'เขียนกิจวัตรของคุณและคนใกล้ตัวรวมสี่ประโยค พร้อมชี้ s ของ verb และ plural noun','I read books at home. Mai reads books at school. I have breakfast at seven. She has breakfast at eight.',['กริยาตรงประธาน','แยก be จากกริยาการกระทำ','ใช้กรรม เวลาและสถานที่ให้เข้าใจ']);
checkpoints[9]=cp([q('My parents help … (พวกเรา)','we|us|our',1,'us เป็นกรรม ย้อน 09.01'),q('Come with … (พวกเขา)','they|their|them',2,'หลัง with ใช้ them ย้อน 09.02'),q('She gives Tom a cup เท่ากับรูปใด?','She gives a cup to Tom.|She gives Tom to a cup.|She gives for Tom a cup.',0,'สิ่งของ + to + ผู้รับ ย้อน 09.03')],'เขียนเรื่องคนสองคนและสิ่งของหนึ่งชิ้น โดยใช้ subject/object pronouns และ give สองรูป','Mai has a pen. She gives it to Ben. Ben likes it. He gives her a book.',['pronoun อ้างกลับชัด','กรรมหลัง verb/preposition ใช้รูป object','ลำดับผู้รับและสิ่งของถูก']);
checkpoints[10]=cp([q('The nurse … work on Sundays.','don’t|doesn’t|isn’t',1,'nurse หนึ่งคนกับ verb work ใช้ doesn’t ย้อน 10.01'),q('ถามผู้ทำใน People work here ใช้รูปใด?','Who works here?|Who does works here?|Who do works here?',0,'Who เป็น subject ไม่เติม do ย้อน 10.05'),q('Where … your friends live?','do|does|are',0,'friends หลายคนกับ live ใช้ do ย้อน 10.03')],'สัมภาษณ์เพื่อนด้วย yes/no สองข้อและ Wh สองข้อ จากนั้นสรุปข้อมูลเป็นสามประโยค','Do you like tea? Yes, I do. Do you play tennis? No, I don’t. Where do you live? In Bangkok. What do you study? English. Ben likes tea. He doesn’t play tennis. He studies English.',['เลือก do/does ตรงประธาน','หลัง do/does ใช้ base','เลือกคำถามตรงข้อมูลและสรุปด้วย s-form ถูก']);
checkpoints.final1=cp([q('A new student says: I … from Thailand.','am|is|are',0,'I ใช้ am: M04'),q('You see one apple for the first time: I have … apple.','a|an|the เท่านั้น',1,'apple เสียงสระและกล่าวครั้งแรก: M05'),q('The two … are teachers.','man|men|mans',1,'man → men: M03'),q('Sara … English every day.','study|studies|is study',1,'Sara เอกพจน์ใช้ studies: M08'),q('Does your brother like music? — No, …','he isn’t|he don’t|he doesn’t',2,'ตอบ Does ด้วย doesn’t: M10'),q('I work with Anna. I work with …','she|her|hers',1,'หลัง with ใช้กรรม her: M09')],'แนะนำตัว 5–6 ประโยค บอกคนใกล้ตัวกับสิ่งของและกิจวัตร จากนั้นตั้งคำถามให้คนอื่นตอบ 4 ข้อ โดยมี be และ do/does ทั้งสองแบบ','I am Mai. I am Thai. I am a student. My sister is a teacher. She reads books. I study English. Are you a student? Where are you from? Do you like books? What do you study?',['ข้อมูลครบและคนอ่านเข้าใจว่าใครเป็นใคร','เลือก pronouns, be, articles และ plural ถูก','เลือก verb s-form ตาม subject','ถามและปฏิเสธด้วย be/do/does ไม่ปนกัน','อ่านออกเสียงแล้วแก้คำที่ทำให้ผู้ฟังไม่เข้าใจ']);
